def wordsFoundInGrid(board, words):
    m, n = len(board), len(board[0])
    root = {}
    for idx, w in enumerate(words):
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node[0] = idx                       # key 0 can never be a letter: it marks the end of a word
    found = []

    def dfs(r, c, parent):
        ch = board[r][c]
        node = parent.get(ch)
        if node is None:
            return
        if 0 in node:
            found.append(node.pop(0))
        board[r][c] = 0                     # visited
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] != 0:
                dfs(nr, nc, node)
        board[r][c] = ch
        if not node:                        # nothing left to find below this node
            del parent[ch]

    for r in range(m):
        for c in range(n):
            dfs(r, c, root)
    found.sort()
    return found
